def icon(name, size=16, stroke=1.75, css_class="", color=None, hidden=False):
    """The HTML of one icon. It takes the text colour of where it sits, unless color is given."""
    class_attr = f' class="{css_class}"' if css_class else ""
    color_attr = color if color else "currentColor"
    hidden_attr = ' aria-hidden="true"' if hidden else ""
    return (
        f'<svg{class_attr}{hidden_attr} width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
        f'stroke="{color_attr}" stroke-width="{stroke}" stroke-linecap="round" stroke-linejoin="round">'
        f"{_PATHS[name]}</svg>"
    )
